/// <summary>
/// MPJ_24248 Pricing Data Extract
/// </summary>
[ExtensionOf(tableStr(InventTableModule))]
Public final class METInventTableModuleTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Table Update
    /// </summary>
    /// <param name="_updatePriceDate">Update</param>
    /// <param name="_updatePrice">Update</param>
    public void update(boolean _updatePriceDate, boolean _updatePrice)
    {
        boolean     fieldUpdated = false;

        if( this.ModuleType  == ModuleInventPurchSales::Sales
        && (this.UnitId != this.orig().UnitId || this.taxItemGroupId != this.orig().taxItemGroupId))
        {
            fieldUpdated = true;
        }
        
        next update(_updatePriceDate, _updatePrice);

        if(fieldUpdated)
        {
            METPriceChangeEventProduct::metProcessTrackChange(InventTable::find(this.ItemId));
        }
    }
